import sys
from collections import defaultdict

def read_input():
    input = sys.stdin.read().strip().split('\n')
    idx = 0
    n, m, k = map(int, input[idx].split())
    idx += 1
    pictures = []
    for _ in range(k + 1):
        picture = []
        for _ in range(n):
            idx += 1
            picture.append(list(map(int, list(input[idx]))))
        pictures.append(picture)
        idx += 1
    return n, m, k, pictures

def get_neighbors(x, y):
    return [(x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)]

def is_valid_operation(n, m, picture, x, y):
    if x == 0 or x == n - 1 or y == 0 or y == m - 1:
        return False
    target_color = picture[x][y]
    opposite_color = 1 - target_color
    for nx, ny in get_neighbors(x, y):
        if picture[nx][ny] != opposite_color:
            return False
    return True

def apply_operation(picture, x, y):
    new_picture = [row[:] for row in picture]
    new_picture[x][y] = 1 - new_picture[x][y]
    return new_picture

def find_initial_and_operations(n, m, k, pictures):
    picture_to_index = {tuple(map(tuple, pic)): i for i, pic in enumerate(pictures)}
    operations = []
    visited = set()
    queue = [(pictures[0], 0)]
    visited.add(tuple(map(tuple, pictures[0])))

    while queue:
        current_picture, current_index = queue.pop(0)
        for x in range(1, n - 1):
            for y in range(1, m - 1):
                if is_valid_operation(n, m, current_picture, x, y):
                    new_picture = apply_operation(current_picture, x, y)
                    new_tuple = tuple(map(tuple, new_picture))
                    if new_tuple not in visited:
                        visited.add(new_tuple)
                        operations.append((1, x + 1, y + 1, picture_to_index[new_tuple]))
                        queue.append((new_picture, picture_to_index[new_tuple]))

        for i in range(k + 1):
            if i != current_index and tuple(map(tuple, pictures[i])) not in visited:
                visited.add(tuple(map(tuple, pictures[i])))
                operations.append((2, i + 1, picture_to_index[pictures[i]]))
                queue.append((pictures[i], picture_to_index[pictures[i]]))

    initial_index = None
    for i, pic in enumerate(pictures):
        if tuple(map(tuple, pic)) not in [op[3] for op in operations if op[0] == 1]:
            initial_index = i + 1
            break

    return initial_index, operations

def main():
    n, m, k, pictures = read_input()
    initial_index, operations = find_initial_and_operations(n, m, k, pictures)
    print(initial_index)
    print(len(operations))
    for op in operations:
        if op[0] == 1:
            print(f"1 {op[1]} {op[2]}")
        else:
            print(f"2 {op[2]}")

if __name__ == "__main__":
    main()
